window.CAST = [
{id:'honey',name:'허니츄러스',color:'#f4a7bf',role:'퇴근길의 유능한 선배',place:'오피스 앞',tag:'당당함 · 빈틈 · 신뢰',events:[
['우산의 지휘권','퇴근길, 비가 갑자기 굵어졌다. 서류 봉투를 든 허니츄러스가 빌딩 입구 차양 아래에서 시계를 보고 있었다.','거기, 새로 이사 온 이웃님. 우산 있으면 같이 가요. 대신 길 안내는 내가 할게.','봉투 모서리에는 이미 빗물이 스며 있었다. 그녀는 자기 어깨보다 서류 쪽을 먼저 살폈다.',['봉투는 제가 들게요. 우산은 가운데로.',2,'…눈치가 빠르네. 회사에서도 그 정도면 내가 데려갔겠다.'],['누나만 믿고 따라갈게요.',1,'좋아요. 그런데 나 이 골목은 처음인데. 지도는 볼 줄 알죠?']],
['완벽한 사람의 오류','회사 행사 준비를 돕기로 했다. 발표 자료 정리를 마친 허니츄러스가 휴대폰 게임 화면을 노려보고 있었다.','업무는 끝났는데 이 미니게임만 안 돼요. 버튼이 왜 도망가?','한 번 더 실패한 그녀가 아무 일 없었다는 듯 자세를 바로잡았다.',['같이 한 판만 해요. 제가 옆에서 알려줄게요.',2,'한 판만이에요. …방금 건 연습이니까 다시.'],['이건 제가 대신 깨드릴게요.',0,'빨리 끝나긴 하겠네요. 그래도 내 손으로 해보고 싶었는데.']],
['반 칸의 자리','행사 전날, 불 꺼진 사무실에서 그녀의 자리만 밝았다. 책상 위에는 식지 않은 도시락이 놓여 있었다.','내일 잘해야 하니까. 다들 나 믿고 준비했거든.','괜찮다는 말과 달리 손끝이 자꾸 같은 페이지에 멈췄다.',['오늘은 제 앞에서 안 괜찮아도 돼요.',2,'그 말… 생각보다 위험하네. 정말 기대고 싶어지잖아.'],['누나라면 반드시 잘할 거예요.',1,'고마워요. 그럼 조금만 더 정리하고 갈게요.']]],good:['퇴근 이후의 우리','행사를 마친 허니츄러스가 출입증을 가방 안에 넣었다.\n“이제 업무 끝. 오늘 저녁 일정은 내가 정해도 돼요?”\n그녀가 내 손을 잡고, 평소보다 천천히 걷기 시작했다.\n누군가의 완벽한 선배가 아닌, 나와 저녁을 고르는 사람이 곁에 있었다.'],normal:['내일도 같은 퇴근길','퇴근 준비를 마친 우리는 사무실 창밖을 보며 비가 잦아들기를 기다렸다.\n“다음 행사에도 도와줄 거죠?”\n나는 고개를 끄덕였다. 아직 사적인 약속은 어색했지만, 나란히 돌아갈 길은 생겼다.']},
{id:'ohwayo',name:'오화요',color:'#c6c7d5',role:'옆집으로 이사 온 누나',place:'아파트 복도',tag:'여유 · 웃음 · 노랫소리',events:[
['벽 너머의 노래','상자를 정리하던 중 옆집에서 노랫소리가 들렸다. 문 앞에 나가자 새 이웃과 마주쳤다.','아, 들렸구나. 시끄러웠어? 내가 정리할 때 노래가 꼭 나와서.','웃으면서 말했지만, 그녀는 내 대답을 기다렸다.',['좋았어요. 다음엔 제목도 알려주세요.',2,'그럼 이사 끝나면 추천곡 하나 보내줄게. 노래값은 귤 한 개.'],['괜찮아요. 저도 가끔 소리 낼 거예요.',1,'서로 시간만 맞추자. 좋은 이웃 협약, 체결!']],
['정전은 계획에 없었다','잠깐 정전이 지나갔다. 복도 조명은 돌아왔지만 엘리베이터에는 점검 표시가 떠 있었다. 맞은편 문틈에서 목소리가 났다.','혹시… 엘리베이터도 멈췄어? 내가 무서워서 그런 건 아니고.','그녀의 손에는 켜지지 않은 손전등이 들려 있었다.',['여기 앉아서 같이 기다릴까요?',2,'응. 그럼 내가 재미있는 이야기 해줄게. 대신 갑자기 놀라게 하기 금지.'],['관리실에 전화하고 돌아올게요.',1,'고마워. 너무 오래 걸리지는 말고. 정말 무서워서 그런 건 아니야.']],
['한 곡을 남기는 이유','공연장 연습 무대에서 오화요는 동네 공연 신청서를 접었다 펼쳤다. 연습하던 곡은 마지막 소절에서 자꾸 끊겼다.','남들 앞에서 부르는 것보다 한 사람한테 들려주는 게 더 떨리네.','그녀가 내 쪽으로 악보를 돌려놓았다.',['그 한 사람이 저여도 괜찮아요?',2,'이미 너 생각하면서 고른 곡인데. 이제 알아챘어?'],['다들 좋아할 거예요. 실력이 좋잖아요.',0,'그러겠지? 응, 일단 연습 더 해볼게.']]],good:['앙코르는 둘이서','작은 무대의 조명이 꺼진 뒤에도 우리는 돌아가지 않았다.\n“오늘 마지막 노래, 누구한테 부른 건지 알지?”\n내 대답을 들은 그녀가 웃었다. 그 웃음은 벽 하나를 건너 듣던 것보다 훨씬 가까웠다.'],normal:['옆집의 플레이리스트','새 추천곡 알림이 도착했다.\n우리는 서로 조용히 쉬고 싶은 시간도, 좋아하는 노래도 알게 됐다.\n복도에서 마주치면 자연스럽게 안부를 묻는, 좋은 이웃이 되었다.']},
{id:'dragon',name:'디디디용',color:'#f2bd65',role:'편의점의 소꿉친구',place:'24시 편의점',tag:'장난 · 오래된 기억 · 용기',events:[
['이사 축하 영수증','편의점 문이 열리자 계산대 뒤에서 익숙한 얼굴이 고개를 들었다.','너 여기로 이사 왔어? 야, 이제 내 근무 시간 외울 일만 남았네.','그녀가 내가 좋아하던 과자를 계산대에 올렸다.',['아직도 이거 기억하고 있었어?',2,'손님 취향 기억하는 것도 실력이지. …너는 손님이랑 좀 다르지만.'],['이사 기념 할인은 없어?',1,'있지. 내가 특별히 정가에 모시겠습니다, 고객님.']],
['웃음이 멈춘 계산대','오늘은 장난을 걸어도 평소 같은 대답이 돌아오지 않았다. 그녀는 창고 문에 붙은 근무표를 보고 있었다.','나도 가끔은 내가 뭘 잘하는지 모르겠어. 맨날 까불기만 하는 것 같고.','나는 던지려던 농담을 잠깐 접었다.',['네가 기억해주는 것들이 좋아. 오늘은 내가 들을게.',2,'그런 말을 그렇게 갑자기 하면 반칙이잖아. 조금만… 얘기해도 돼?'],['에이, 너답지 않게 왜 그래.',0,'그치. 내가 괜히 진지해졌네. 봉투 필요해?']],
['익숙한 사이의 새 이름','교대를 마친 디디디용이 편의점 냉장고에서 음료 두 개를 꺼냈다.','너 다른 사람 만나도 여기 계속 올 거야? 단골 잃으면 곤란하거든.','장난처럼 끝난 말인데 캔을 따는 손이 늦었다.',['편의점이 아니라 너 보러 오는 건데.',2,'…진짜? 지금 옛날처럼 놀리는 거 아니지?'],['당연하지. 너는 제일 오래된 친구잖아.',1,'응. 오래된 친구. 그건 내가 자신 있지.']]],good:['영수증 뒷면의 고백','그녀가 영수증 한 장을 건넸다. 뒷면에는 내일의 약속 시간과 작은 공룡이 그려져 있었다.\n“이건 단골 서비스 아니야. 너한테만 주는 거야.”\n오래 알고 지낸 이름을, 오늘부터 조금 다르게 부르기로 했다.'],normal:['언제나 불 켜진 곳','지친 날이면 편의점 불빛이 먼저 반겨준다.\n“왔냐? 네 거 남겨놨다.”\n우리는 아직 서로에게 가장 편한 친구다. 그 익숙함도 소중히 지키기로 했다.']},
{id:'yui',name:'담유이',color:'#8fd5e8',role:'반찬을 나눠주는 누나',place:'공동 주방',tag:'다정함 · 엉뚱함 · 함께',events:[
['반찬과 사용 설명서','초인종이 울렸다. 담유이는 반찬통 세 개와 손글씨 쪽지를 들고 있었다.','이건 오늘 먹고, 이건 내일. 통은 빌려주는 거야. 반찬통 인질 작전이지.','쪽지 구석에는 삐뚤빼뚤한 낙서도 있었다. 보고 있자니 저절로 웃음이 났다.',['맛있게 먹고 설거지해서 돌려드릴게요.',2,'좋아요. 반찬통 신뢰도 상승! 먹고 뭐가 제일 좋았는지도 알려줘.'],['매일 가져다주시면 안 돼요?',0,'누나가 급식소는 아니거든요? 일단 오늘 것부터 잘 먹기!']],
['부엌의 플레이리스트','반찬통을 돌려주러 갔더니 공동 주방에서 음악이 흘러나왔다. 그녀는 국자를 마이크처럼 들고 있었다.','봤어? 방금 건 조리 과정이야. 리듬을 넣어야 맛이 깊어진다고.','도마 한쪽에는 아직 썰지 못한 채소가 쌓여 있었다.',['그럼 저는 박자 맞춰서 채소 썰게요.',2,'좋아. 하지만 손가락은 박자에서 빼. 안전한 듀엣으로 가자.'],['재미있네요. 영상 찍어도 돼요?',1,'오늘은 비공개 공연! 대신 설거지 관객석은 비어 있어.']],
['빈 반찬통 대신','공동 주방에 도착했지만 담유이는 아직 오지 않았다. 휴대폰에 오늘은 조금 지쳤다는 메시지가 도착했다.','[메시지] 미안. 오늘은 요리할 힘이 안 나네. 너 밥은 먹었어?','나는 준비해 온 음식이 든 봉투를 내려다봤다.',['오늘은 제가 준비했어요. 같이 먹을래요?',2,'나한테 반찬 들고 오는 사람도 생기네. 이상하게 기분 좋다.'],['괜찮아요. 배달 시켜 먹을게요.',1,'응, 굶지만 마. 나는 조금 쉬고 연락할게.']]],good:['두 사람 몫의 식탁','식탁에 서로 다른 반찬통이 놓였다. 더 잘 만든 쪽을 가리다가 둘 다 웃어버렸다.\n“내일도 두 사람 몫으로 하면 되지?”\n챙겨주는 사람과 챙김을 받는 사람 대신, 우리는 함께 저녁을 만드는 사이가 되었다.'],normal:['오가는 반찬통','새로 만든 반찬을 나누고, 좋아하는 노래를 추천하는 일이 일상이 됐다.\n그녀의 장난스러운 메모는 여전히 냉장고에 붙어 있다.\n혼자 사는 집에도 누군가의 다정함이 드나들 수 있다는 걸 배웠다.']},
{id:'aya',name:'아야',color:'#c7afe8',role:'첫 자취를 시작한 지인',place:'이삿짐 가득한 방',tag:'조곤조곤 · 끈기 · 첫걸음',events:[
['나사 하나의 독립','아야는 조립 설명서를 거꾸로 들고 작은 책장 앞에 앉아 있었다.','이상하다. 분명 그림대로 했는데… 나사 하나가 남아요.','도와달라는 말보다 다시 해보겠다는 말이 먼저 나왔다.',['같이 순서부터 볼까요? 조립은 아야가 해요.',2,'좋아요. 이번에는 제가 꼭 맞춰볼게요. 옆에서 봐줘요.'],['제가 다 할 테니 쉬고 있어요.',0,'고맙긴 한데… 이건 제가 해보고 싶었어요.']],
['조용한 승부욕','책장이 완성된 방에 게임 효과음이 울렸다. 아야는 같은 구간에 계속 도전하고 있었다.','이번에는 될 것 같아요. 아까보다 조금 더 갔어요.','여러 번 실패했지만 목소리는 여전히 조용하고 단단했다.',['한 번 쉬고 와요. 다음 도전도 옆에서 볼게요.',2,'안 가고 기다려줘요? 그럼 물부터 마시고 올게요.'],['어려우면 그만해도 괜찮아요.',1,'응. 그래도 오늘은 조금만 더 해보고 싶어요.']],
['처음 차린 손님상','문 앞에 손님용 슬리퍼가 가지런히 놓여 있었다. 아야가 직접 만든 음식을 내왔다.','오늘은 도와달라고 부른 거 아니에요. 제가 차린 밥을 대접하고 싶었어요.','그녀는 내가 의자에 앉기 전까지 계속 식탁을 정리했다.',['이렇게 식사에 초대해줘서 기뻐요.',2,'다음에도 와요. 다음에는 메뉴도 같이 정해요.'],['이제 혼자서도 잘하겠네요.',0,'그렇죠? 혼자서도… 응, 잘해볼게요.']]],good:['한 사람 몫의 슬리퍼','아야의 현관에 내 슬리퍼가 생겼다.\n“이거 두면 또 올 것 같아서요.”\n누군가 대신 꾸민 집이 아니라, 그녀가 스스로 만든 공간에 초대받았다.\n우리는 다음 주의 저녁 메뉴를 함께 적었다.'],normal:['스스로 켜는 불','책장에는 아야가 고른 책들이 차곡차곡 채워졌다.\n그녀는 이제 필요한 것을 자기 목소리로 부탁할 수 있다.\n“이사 도와줘서 고마웠어요. 다음에는 제가 도와줄게요.”']},
{id:'siyo',name:'하시요',color:'#9baaf4',role:'랭크에서 만난 라이벌',place:'동네 PC방',tag:'승부욕 · 티격태격 · 듀오',events:[
['현피 대신 라면','게임에서 다투고 만나기로 한 상대가 PC방 안쪽 자리에서 손을 들었다.','너였냐? 좋아. 말로 싸우지 말고 리플레이부터 보자.','거창한 대결 장소라고 해봐야 나란히 놓인 컴퓨터 두 대가 전부였다. 어디선가 라면 냄새가 났다.',['내 실수부터 같이 보자.',2,'오, 인정할 건 인정하네? 그럼 나도 그때 들어간 건 실수였어.'],['일단 1대1부터 하자.',1,'좋아. 지고 키보드 탓하기 없기다.']],
['핑보다 먼저 오는 말','연패한 하시요가 새 게임 버튼 위에서 손을 멈췄다.','한 판만 더 이기면 끝낼 수 있는데. 지금 끄면 너무 억울해.','농담으로 넘기려는 목소리에 피곤함이 묻어났다.',['오늘은 쉬자. 내일도 같이 돌리면 되잖아.',2,'내일도? 약속했다. 그럼 라면만 먹고 가자.'],['이길 때까지 달리자.',0,'좋아. …근데 손이 좀 느리네, 오늘.']],
['빈 듀오 자리','메신저에 짧은 질문이 도착했다. 오늘 누구랑 하냐는 말이었다.','누구랑 돌리는지 그냥 물어본 거야. 조합 확인하려고.','그녀의 상태 메시지는 한참 전부터 온라인이었다.',['너랑 하려고 기다리고 있었어.',2,'그럼 빨리 들어와. 아니, 밥부터 먹었어? 안 먹었으면 기다릴게.'],['빈자리 있으면 초대할게.',0,'응. 자리 나면 불러. 나도 다른 거 하고 있을게.']]],good:['다음 판도, 다음 날도','마지막 게임이 끝났는데도 둘 다 헤드셋을 벗지 않았다.\n“게임 꺼도 통화는 켜놔.”\n나는 웃으며 내일은 밖에서 만나자고 했다.\n그녀는 처음으로 승률 대신 약속 장소를 물었다.'],normal:['믿을 만한 서포터','서로 실수를 숨기지 않는 듀오가 됐다.\n“오늘도 잘 부탁한다.”\n승패와 상관없이 끝나고 인사할 사람이 있다는 것이, 생각보다 게임을 즐겁게 만들었다.']},
{id:'mone',name:'비올레타 모네',color:'#c3b1e4',role:'밤이 긴 대학 선배',place:'대학 도서관',tag:'잔잔함 · 퍼즐 · 긴 대화',events:[
['책갈피의 수수께끼','도서관에서 빌린 책에 낯선 책갈피가 끼어 있었다. 모네 선배가 맞은편에서 손을 흔들었다.','그거 내 거야. 뒷면 문제 풀어봤어? 그냥 낙서인데.','책갈피에는 작은 논리 퍼즐이 적혀 있었다.',['같이 풀어봐도 돼요?',2,'응. 답보다 어떻게 생각하는지 듣는 게 재미있거든.'],['정답부터 알려주세요.',1,'바로? 그럼 재미없는데. 힌트 하나만 줄게.']],
['책을 덮은 뒤에도','빌린 책을 반납하고도 대화가 끝나지 않았다. 퍼즐에서 시작한 이야기가 좋아하는 노래까지 번졌다.','나 말 많이 하지? 조용한 사람인 줄 알았다는 얘기 자주 듣거든.','선배는 책을 넣으며 내 눈치를 살폈다.',['선배 얘기 더 듣고 싶어요. 산책할까요?',2,'그럼 정문까지만. …조금 돌아가도 괜찮고.'],['이제 가봐야겠네요. 다음에 들어요.',1,'맞다. 잘 가. 책갈피는 당분간 가지고 있어.']],
['답이 없는 문제','선배가 새 퍼즐 대신 빈 종이를 내밀었다.','좋아하는 사람이 있으면 어떻게 말할 것 같아? 아, 이야기 속 인물 얘기야.','그녀는 빈 종이 모서리를 천천히 접었다.',['지금 같이 있는 시간이 좋다고 말할래요.',2,'그럼 나도 그렇게 말할게. 지금, 같이 있어서 좋아.'],['상대가 먼저 말할 때까지 기다리겠죠.',0,'그러면 둘 다 기다리기만 할 수도 있겠네. 어려운 문제다.']]],good:['책갈피 다음 장','책갈피 뒷면에 새로운 문장이 적혀 있었다. 다음 토요일, 두 시.\n“이번엔 퍼즐 아니야. 데이트 신청.”\n우리는 정답을 맞히는 대신 서로의 생각을 오래 듣는 연습을 시작했다.'],normal:['끝나지 않는 독서 모임','책을 반납할 때마다 서로의 추천 목록이 길어졌다.\n서로 다른 답을 말해도 편안한 사람이 생겼다.\n선배는 오늘도 조용하게, 그리고 아주 오래 이야기했다.']},
{id:'rose',name:'블레어 로즈',color:'#ee8c9a',role:'취향 공유가 일상인 여사친',place:'만화책방',tag:'영애 말투 · 장난 · 솔직함',events:[
['추천은 새벽 세 시','새벽에 보낸 캐릭터 그림 이야기를 하려고 로즈가 만화책방에서 기다리고 있었다.','이 아가씨의 안목을 평가할 기회라는 거시에요. 어느 쪽이 더 좋으신가요?','그녀는 두 권의 표지를 진지하게 비교했다.',['왜 좋아하는지부터 듣고 싶어.',2,'설명을 허락하신 거예요? 자, 이 인물의 서사부터 시작하겠어요!'],['둘 다 예쁘네.',1,'평가는 안전하지만 성의가 부족한 거시에요. 추가 설명 들어갑니다.']],
['장난의 경계','로즈가 평소보다 과장된 장난을 던지고는 내 표정을 확인했다.','왜요? 오늘은 조용하시네요. 이 아가씨가 재미없어졌나요?','내가 웃지 않자 그녀도 말을 멈췄다.',['오늘은 조금 지쳤어. 그냥 같이 있어줄래?',2,'…그런 건 미리 말하는 거시에요. 오늘은 조용히 옆에 있겠어요.'],['아니야, 계속해. 재미있어.',0,'그래요? 그럼… 평소처럼 하면 되는 거죠?']],
['대본에 없는 한마디','함께 고른 책을 계산한 뒤, 로즈가 책방 문 옆에서 오늘은 어땠냐고 물었다.','최고의 동행이었지요? 당연하지만 직접 평가도 듣겠어요.','그녀의 말투는 당당했지만 시선은 자꾸 다른 곳으로 갔다.',['장난 말고 진심으로, 너랑 있어서 좋았어.',2,'…잠깐만요. 그런 건 예고하고 말해요. 답변을 준비해야 하잖아요.'],['역시 넌 재미있는 친구야.',1,'물론이에요. 재미만큼은 보장하는 친구인 거시에요.']]],good:['대본 없는 데이트','로즈가 오늘은 그림 대신 짧은 메시지를 보냈다.\n“책 말고, 저 보러 오실래요?”\n만나자마자 쏟아질 줄 알았던 장난 대신 수줍은 인사가 왔다.\n우리는 준비한 대사 없이도 함께 걸을 수 있었다.'],normal:['취향을 나누는 사이','추천 메시지는 이제 서로 편한 시간에 주고받는다. 내가 먼저 추천을 보내는 날도 있다.\n“역시 이해가 빠른 친구인 거시에요.”\n서로의 엉뚱한 취향을 놀리지 않고 들어주는 든든한 친구가 되었다.']},
{id:'popo',name:'포포포포',color:'#9ebfee',role:'부산 사투리의 카페 알바',place:'골목 카페',tag:'장난 · 부산 억양 · 반전',events:[
['주문은 이미 알고 있다','카페에 들어가자 포포포포가 컵을 꺼냈다. 아직 주문하지도 않았는데 얼음 소리가 났다.','오늘도 그거 맞제? 아니면 이건 내가 마시고.','컵에는 내가 늘 고르는 음료 이름이 적혀 있었다.',['내 주문 기억해줬네. 고마워.',2,'단골인데 당연하지. …맨날 같은 시간에 와서 그런 기다.'],['오늘은 다른 걸 마실래.',1,'변화 주는 날이가? 좋다. 오늘 추천은 내가 책임진다.']],
['카페 밖에서는','퇴근한 포포포포와 공원 산책길에서 마주쳤다. 카운터 안에서와 달리 인사가 작아졌다.','어… 아직 안 갔나. 나도 이제 집에 가는데.','가게 안에서 하던 농담을 꺼내려던 그녀가 말 대신 조용히 웃었다.',['천천히 같이 걸을래?',2,'그래. 나 오늘 있었던 일 하나만 얘기해도 되나?'],['밖에서는 왜 이렇게 조용해?',0,'그냥… 밖이라서. 가게에서 보는 거랑은 좀 다르잖아.']],
['마감 후 한 잔','마감 정리를 끝낸 카페에 우리 자리의 접시만 남아 있었다. 포포포포가 작은 접시를 들고 왔다.','새 메뉴 연습한 건데. 니부터 먹여… 아니, 니한테 먼저 맛봐달라고.','접시에는 조금 삐뚤어진 디저트 두 개가 놓여 있었다.',['너도 앉아. 같이 먹자.',2,'그럴까. 오늘은 손님이랑 알바 말고 그냥 같이 먹는 기다.'],['평가표 써주면 돼?',1,'그래도 되는데… 너무 심사위원처럼 먹지는 말고.']]],good:['단골에서 약속으로','오늘 카페 문에는 휴무 팻말이 걸렸다. 그녀는 앞치마 대신 가벼운 외투를 입고 나왔다.\n“오늘 주문은 내가 할게. 같이 놀아주기 한 잔.”\n우리는 처음으로 가게의 영업시간과 상관없는 약속을 했다.'],normal:['나를 기억하는 카페','말하지 않아도 익숙한 컵이 준비되는 곳이 생겼다.\n포포포포는 새 메뉴를 연습할 때마다 나를 불렀다.\n골목을 좋아하게 된 이유 중 하나가, 매일 이 자리에서 웃고 있다.']},
{id:'siho',name:'류시호',color:'#e0c394',role:'온라인에서 만난 게임 친구',place:'게임 라운지',tag:'고인물 · 낯가림 · 작은 용기',events:[
['채팅창 밖에서','함께 게임하던 류시호와 처음 만났다. 맞은편에 앉았는데 휴대폰으로 인사가 도착했다.','[메시지] 안녕하세요. 실제로 만나니까 말이 잘 안 나와요.','게임에서는 늘 앞장서던 그녀가 컵을 꼭 쥐고 있었다.',['[메시지] 천천히 해요. 여기 커피 괜찮네요.',2,'[메시지] 그쵸. 추천하고 싶어서 여기로 골랐어요.'],['게임할 때처럼 편하게 말해봐요.',0,'그러고 싶은데… 그게 바로는 잘 안 돼요.']],
['오늘은 내가 길잡이','게임에서 길을 잃자 류시호가 바로 돌아왔다. 늘 빠르던 사람이 이번에는 내 속도에 맞춰 걸었다.','여기 함정 있어요. 급하게 안 와도 돼요. 기다릴게요.','나는 이전에 카페에서 함께 기다렸던 시간을 떠올렸다.',['기다려줘서 고마워요. 같이 가니까 좋네요.',2,'저도요. 혼자 깨는 것보다 지금이 더 재미있어요.'],['먼저 가요. 알아서 따라갈게요.',1,'그럼 앞에서 길 정리하고 있을게요. 필요하면 꼭 불러요.']],
['음성 연결 중','밤늦게 메시지가 왔다. 게임 초대일 줄 알았는데 통화 요청이었다.','오늘은 게임 안 해도 괜찮아요? 그냥… 이야기하고 싶어서.','평소보다 긴 침묵 끝에 그녀가 먼저 내 하루를 물었다.',['좋아요. 저도 목소리 듣고 싶었어요.',2,'다행이다. 이 버튼 누르기까지 되게 오래 고민했거든요.'],['무슨 일 있어요? 급한 건가요?',0,'급한 건 아닌데… 아니에요. 다음에 게임할 때 얘기해요.']]],good:['접속 중이 아닌, 곁에','류시호가 먼저 만날 장소를 보냈다. 카페 밖에서 그녀가 손을 흔들었다.\n“오늘은 제가 먼저 인사했어요.”\n작은 목소리가 골목의 소음 사이로 또렷하게 들렸다.\n우리는 온라인 표시가 없어도 서로를 찾을 수 있게 되었다.'],normal:['돌아갈 파티가 있다','게임에 접속하면 익숙한 초대장이 온다.\n“오늘은 어디부터 갈까요?”\n현실에서는 아직 조금 서툴러도, 서로의 속도를 기다릴 수 있는 친구가 되었다.']},
{id:'ori',name:'오리고기',color:'#e9d576',role:'남의 이야기를 잇는 편집자',place:'작은 편집실',tag:'관찰 · 무심한 다정함 · 주인공',events:[
['잘린 장면의 바깥','동네 행사 영상 정리를 돕다가 편집실을 찾았다. 오리고기는 모니터 너머로 손만 흔들었다.','파일은 날짜순으로 부탁해요. 추억은 순서가 없어도 편집에는 필요하거든요.','완성된 영상 어디에도 그녀의 모습은 없었다.',['누나가 찍힌 영상은 없어요?',2,'저는 찍는 쪽이라서요. …그걸 찾아본 사람은 처음이네.'],['정리만 끝내면 되는 거죠?',1,'네. 헷갈리는 파일은 따로 두세요. 제가 볼게요.']],
['휴식의 러닝타임','편집실 시계는 약속한 휴식 시간을 한참 넘기고 있었다. 오리고기는 식은 커피 옆에서 같은 장면을 반복했다.','다른 사람은 이 장면이 제일 좋대요. 근데 나는 앞에 웃는 장면도 아까워서.','주인공을 잘 보이게 하는 일에 그녀는 쉽게 타협하지 않았다.',['누나가 좋아하는 장면도 남겨요.',2,'그래도 될까요. …그럼 같이 봐줘요. 왜 좋은지 설명할게요.'],['다수가 좋다는 쪽으로 하면 되죠.',0,'그게 효율적이긴 하죠. 일단 그 버전으로 내보낼게요.']],
['오늘은 상담하지 않는다','그녀는 습관처럼 내가 다른 이웃과 어떻게 지내는지 물었다. 나는 가져온 음료를 책상에 놓았다.','오늘은 누구 얘기예요? 표정 보니까 뭔가 있었네.','늘 다른 사람 이야기를 듣던 그녀가 의자를 돌렸다.',['오늘은 누나 보러 왔어요.',2,'…잠깐. 방금 말, 농담으로 잘라내기에는 너무 아까운데. 진심으로 한 말이에요?'],['누구를 초대하면 좋을지 상담하려고요.',0,'아. 네, 그럼 처음부터 천천히 이야기해봐요.']]],good:['엔딩 크레딧 앞에서','상영이 끝난 뒤 카메라를 내려놓고 옆자리를 비웠다.\n“오늘은 찍지 말고 같이 있어요.”\n오리고기가 조심스레 내 옆에 앉았다.\n“남의 좋은 장면은 잘 찾는데… 이 장면은 어떻게 남겨야 할지 모르겠네.”\n우리는 녹화 버튼을 누르지 않고도 오래 기억할 저녁을 보냈다.'],normal:['좋은 장면을 고르는 사람','동네 영상의 마지막에 편집자의 이름이 올랐다.\n나는 누구보다 먼저 박수를 쳤다.\n그녀는 조금 당황하다가 웃었다. 남을 비추는 사람에게도 응원을 건넬 수 있게 됐다.']}
];
